defmodule Ash.DataLayer.Ets.Info do
  @moduledoc "Introspection helpers for the Ets data layer"

  alias Spark.Dsl.Extension

  @doc "Whether or not the ets table for the resource should be private"
  @spec private?(Ash.Resource.t() | Spark.Dsl.t()) :: boolean
  def private?(resource) do
    Extension.get_opt(resource, [:ets], :private?, false, true)
  end

  @doc "The ets table name for a resource"
  @spec table(Ash.Resource.t() | Spark.Dsl.t()) :: boolean
  def table(resource) do
    Extension.get_opt(resource, [:ets], :table, resource, true) || resource
  end

    {base, interface.name}
  else
    {interface.name, :"#{interface.name}!"}
  end

{can_fn, can_question_fn} =
  if predicate? do
    {:"can_#{action_fn}", :"can_#{bang_fn}"}
  else
    {:"can_#{interface.name}", :"can_#{interface.name}?"}
  end

if :action in interface.functions do
  @dialyzer {:nowarn_function, {action_fn, length(common_args) + 2}}
  @doc Ash.CodeInterface.docs(
         resource,
         action,
         interface.args,
         interface.exclude_inputs,
         interface.custom_inputs,
         interface_options
       )
  @doc spark_opts: [
         {first_opts_location, interface_options.schema()},
         {first_opts_location + 1, interface_options.schema()}
       ]

